		constexpr unsigned int kHandleEntryMask = 0xFFFF;
		constexpr unsigned int kHandleSerialShift = 16;

		static_assert(std::numeric_limits<unsigned int>::digits == 32);

		// Constructor-free handle facade: SDK method names/validity are exact;
		// entry/serial packing is synthetic, not an SDK layout or engine claim.
		struct CBaseHandle {
			unsigned int m_Index;

			static CBaseHandle UnsafeFromIndex(const int nValue) {
				return { static_cast<unsigned int>(nValue) };
			}

			void Init(const int nEntryIndex, const int nSerialNumber) {
				m_Index = (static_cast<unsigned int>(nEntryIndex) & kHandleEntryMask) | (static_cast<unsigned int>(nSerialNumber) << kHandleSerialShift);
			}

			int ToInt() const {
				return static_cast<int>(m_Index);
			}

			int GetEntryIndex() const {
				return static_cast<int>(m_Index & kHandleEntryMask);
			}

			int GetSerialNumber() const {
				return static_cast<int>(m_Index >> kHandleSerialShift);
			}

			bool IsValid() const {
				return m_Index != std::numeric_limits<unsigned int>::max();
			}
		};

		// SDK Vector facade: preserve exact Init/x/y/z spellings, not its ABI.
		// NaN defaults expose a premature read; the actual parsers must initialize.
		struct Vector {
			Vector();
			Vector(const float flX, const float flY, const float flZ) noexcept;
			void Init(const float flX, const float flY, const float flZ);

			float x;
			float y;
			float z;
		};

		Vector::Vector() {
			x = std::numeric_limits<float>::quiet_NaN();
			y = std::numeric_limits<float>::quiet_NaN();
			z = std::numeric_limits<float>::quiet_NaN();
		}

		Vector::Vector(const float flX, const float flY, const float flZ) noexcept :
			x(flX),
			y(flY),
			z(flZ)
		{
		}

		void Vector::Init(const float flX, const float flY, const float flZ) {
			x = flX;
			y = flY;
			z = flZ;
		}

