		// Controlled storage facade for actual sound parsing, not SDK allocation or ABI.
		template <typename TValue>
		class CUtlVector {
		public:
			CUtlVector() = default;

			void EnsureCapacity(const int nCapacity) {
				if (nCapacity < 0) {
					throw std::length_error("CUtlVector fixture capacity must not be negative.");
				}

				m_vecValues.reserve(static_cast<std::size_t>(nCapacity));
			}

			TValue* Base() {
				return m_vecValues.data();
			}

			void Swap(CUtlVector& vecValues) {
				m_vecValues.swap(vecValues.m_vecValues);
			}

			void RemoveAll() {
				m_vecValues.clear();
			}

			int AddToTail(TValue const& Value) {
				constexpr std::size_t kMaximumElementCount = static_cast<std::size_t>(std::numeric_limits<int>::max());

				if (m_vecValues.size() >= kMaximumElementCount) {
					throw std::length_error("CUtlVector fixture exceeds the SDK int count range.");
				}

				m_vecValues.push_back(Value);

				return static_cast<int>(m_vecValues.size() - 1);
			}

			int Count() const {
				return static_cast<int>(m_vecValues.size());
			}

			TValue const& operator[](const int nIndex) const {
				return m_vecValues[static_cast<std::size_t>(nIndex)];
			}

		private:
			std::vector<TValue> m_vecValues;
		};

