#if defined(SOURCEJS_FIXTURE_TRACE_NOEXCEPT_TERMINATION)
		void InstallTraceNoexceptTerminationProbe() noexcept {
			std::set_terminate([]() noexcept -> void {
				if (g_unMessageCalls == g_unMessageFaultCall) {
					std::fputs("Module binding error fixture: controlled trace noexcept termination\n", stderr);
					std::fflush(stderr);
				}

				std::_Exit(1);
			});
		}
#endif // defined(SOURCEJS_FIXTURE_TRACE_NOEXCEPT_TERMINATION)

		void Require(const bool bCondition, char const* const pszMessage) {
			if (!bCondition) {
				throw std::runtime_error(pszMessage);
			}
		}

		void TerminateScript(v8::Isolate* const pIsolate) {
			v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
			v8::Local<v8::Script> LocalScript {};
			Require(v8::Script::Compile(LocalContext, v8::String::NewFromUtf8Literal(pIsolate, "1")).ToLocal(&LocalScript), "Compile termination probe");
			pIsolate->TerminateExecution();
			v8::Local<v8::Value> LocalResult {};
			const bool bCompleted = LocalScript->Run(LocalContext).ToLocal(&LocalResult);
			Require(!bCompleted && pIsolate->IsExecutionTerminating(), "Enter real execution termination");
		}

