		IPlayerInfo* GetPlayerInformationFromIndex(const int nPlayerIndex, edict_t** const ppEdictOut) {
			if (nPlayerIndex != 4) {
				return nullptr;
			}

			ExecuteBackend(v8::Isolate::GetCurrent());

			if (!g_bPlayerAvailable) {
				return nullptr;
			}

			if (ppEdictOut) {
				*ppEdictOut = &g_PlayerEdict;
			}

			return &g_PlayerInformation;
		}

		IPlayerInfo* RequirePlayerInformationFromIndex(v8::Isolate* const pIsolate, const int nPlayerIndex, edict_t** const ppEdictOut, char const* const pszOperation) {
			constexpr char const* kOperations[] = {
				"Player.Kick()",
				"Player.Ban()",
				"Player.ChangeTeam()",
				"Player.SetName()",
				"Player.Name",
				"players.GetName()",
				"players.GetTeam()",
				"players.GetUserID()",
				"players.GetNetworkID()",
				"players.GetOrigin()",
				"players.IsConnected()",
				"players.IsFakeClient()",
				"players.IsDead()",
				"players.SetName()",
				"players/teams.ChangePlayerTeam(nEntityIndex, Team)",
			};

			auto const MatchesOperation = [pszOperation](char const* const pszExpected) {
				return std::string_view(pszOperation) == pszExpected;
			};
			Require(std::any_of(std::begin(kOperations), std::end(kOperations), MatchesOperation), "Player lookup operation");

			if (g_bTrackPlayerLookup) {
				ExecuteBackend(pIsolate);
			}

			if (ppEdictOut) {
				*ppEdictOut = nullptr;
			}

			if ((nPlayerIndex != 4) || !g_bPlayerAvailable) {
				ThrowError(pIsolate, "Synthetic player lookup unavailable.");
				return nullptr;
			}

			if (ppEdictOut) {
				*ppEdictOut = &g_PlayerEdict;
			}

			return &g_PlayerInformation;
		}

