		// MD5 SDK adapter checks the exact UTF-8 byte span and emits a fixed digest.
		// It does not implement MD5 or model allocator/encoding OOM behavior.
		struct MD5Context_t {};

		constexpr std::size_t kFixtureDigestByteCount = 16;
		char const* g_pchExpectedChecksumBytes = "";
		unsigned int g_unExpectedChecksumByteCount = 0;
		unsigned int g_unChecksumUpdateCalls = 0;
		bool g_bChecksumEncodingFailure = false;
		bool g_bChecksumPendingException = false;

		void MD5Init(MD5Context_t* const pContext) {
			Require(pContext != nullptr, "Initialize a non-null adapted checksum context");
			ExecuteBackend(v8::Isolate::GetCurrent());
		}

		void MD5Update(MD5Context_t* const pContext, unsigned char const* const pchBytes, const unsigned int unByteCount) {
			Require(pContext && pchBytes && (unByteCount == g_unExpectedChecksumByteCount), "Preserve checksum byte count");
			Require(std::memcmp(pchBytes, g_pchExpectedChecksumBytes, unByteCount) == 0, "Preserve every UTF-8 checksum byte including NUL");

			++g_unChecksumUpdateCalls;
		}

		void MD5Final(unsigned char* const pchDigest, MD5Context_t* const pContext) {
			constexpr unsigned int kDigestByteMultiplier = 0x11;

			Require(pContext && pchDigest, "Finalize a non-null adapted digest");

			for (std::size_t unDigestIndex = 0; unDigestIndex < kFixtureDigestByteCount; ++unDigestIndex) {
				pchDigest[unDigestIndex] = static_cast<unsigned char>(unDigestIndex * kDigestByteMultiplier);
			}
		}

