		char const* ReadFixtureEventUTF8Value(v8::Isolate* const pIsolate, char const* const pszValue) {
			const MessageFault Fault = g_EventUTF8Fault;
			if (Fault == MessageFault::None) {
				return pszValue;
			}

			++g_unEventUTF8Calls;
			if (g_unEventUTF8Calls < g_unEventUTF8FaultCall) {
				return pszValue;
			}

			g_EventUTF8Fault = MessageFault::None;
			g_unEventUTF8Calls = 0;

			if ((Fault == MessageFault::PendingException) || (Fault == MessageFault::PendingCppException)) {
				pIsolate->ThrowException(v8::True(pIsolate));
			}

			if ((Fault == MessageFault::CppException) || (Fault == MessageFault::PendingCppException)) {
				throw std::runtime_error("Synthetic event UTF-8 result failure");
			}

			if ((Fault == MessageFault::Empty) || (Fault == MessageFault::PendingException)) {
				return nullptr;
			}

			return pszValue;
		}

