#ifdef SOURCEJS_HAS_BASE_ENTITY
		constexpr std::size_t kFixtureDatamapStringSlotCount = 4;
		char g_arrDatamapPooledStrings[kFixtureDatamapStringSlotCount][kFixtureEntityPropertyByteCount] {};
#endif
		std::size_t g_unDatamapStringAllocations = 0;
		std::size_t g_unDatamapStringSlot = 0;
		bool g_bDatamapStringAllocationSucceeds = true;
		bool g_bDatamapStringAllocationRecyclesEntity = false;
		bool g_bDatamapPropertyNameCppFault = false;

#ifdef SOURCEJS_HAS_BASE_ENTITY
		datamap_t* CBaseEntity::GetDataDescMap() {
			++g_unDatamapLookupCalls;
			ExecuteBackend(v8::Isolate::GetCurrent());

			return &g_OutputDatamap;
		}

		bool AllocateEntityInputString(std::string const& strValue, string_t& StringOut) {
			++g_unDatamapStringAllocations;

			if (strValue.empty() || (strValue.front() == '\0')) {
				StringOut = {};
				return true;
			}

			ExecuteBackend(v8::Isolate::GetCurrent());

			if (!g_bDatamapStringAllocationSucceeds || (strValue.size() >= kFixtureEntityPropertyByteCount) || (g_unDatamapStringSlot >= kFixtureDatamapStringSlotCount)) {
				return false;
			}

			char* const pszPoolValue = g_arrDatamapPooledStrings[g_unDatamapStringSlot];
			++g_unDatamapStringSlot;
			const std::size_t unMaximumCopyByteCount = std::min(kFixtureEntityPropertyByteCount - 1, strValue.size());
			char const* const pszValueTerminator = static_cast<char const*>(std::memchr(strValue.data(), '\0', unMaximumCopyByteCount));
			const std::size_t unCopyByteCount = pszValueTerminator ? static_cast<std::size_t>(pszValueTerminator - strValue.data()) : unMaximumCopyByteCount;
			std::memcpy(pszPoolValue, strValue.data(), unCopyByteCount);
			std::memset(pszPoolValue + unCopyByteCount, '\0', kFixtureEntityPropertyByteCount - unCopyByteCount);

			if (g_bDatamapStringAllocationRecyclesEntity) {
				g_DatamapEntityHandle.Init(g_DatamapEntityHandle.GetEntryIndex(), g_DatamapEntityHandle.GetSerialNumber() + 1);
			}

			StringOut.m_pszValue = pszPoolValue;

			return true;
		}
#endif

