		// Controlled message storage/lookup, not SDK layouts or live engine dispatch.
		class FixtureUserMessageBitWriter {
		public:
			void WriteUBitLong(const std::uint32_t unBitValue, const int nBitCount, const bool bCheckRange);
			int GetNumBitsLeft() const noexcept;
			bool IsOverflowed() const noexcept;
		};

		constexpr int kFixtureUserMessageBitCapacity = 32;
		int g_nFixtureUserMessageRemainingBits = kFixtureUserMessageBitCapacity;
		bool g_bFixtureUserMessageOverflowed = false;
		unsigned int g_unFixtureUserMessageWriteCalls = 0;
		int g_nFixtureUserMessageLastBitCount = 0;
		std::uint32_t g_unFixtureUserMessageLastBitValue = 0;

		void FixtureUserMessageBitWriter::WriteUBitLong(const std::uint32_t unBitValue, const int nBitCount, const bool bCheckRange) {
			Require(nBitCount != 0, "Never dispatch a zero-bit user-message write to the SDK");
			Require((nBitCount > 0) && (nBitCount <= kFixtureUserMessageBitCapacity) && (nBitCount <= g_nFixtureUserMessageRemainingBits), "Validate user-message bit width and capacity before SDK dispatch");
			Require((nBitCount == kFixtureUserMessageBitCapacity) || (unBitValue < (std::uint32_t(1) << nBitCount)), "Never send high bits outside the user-message field width to the SDK");
			Require(!bCheckRange, "Preserve the SDK bit-write range-check mode");

			++g_unFixtureUserMessageWriteCalls;
			g_nFixtureUserMessageLastBitCount = nBitCount;
			g_unFixtureUserMessageLastBitValue = unBitValue;
			g_nFixtureUserMessageRemainingBits -= nBitCount;
		}

		int FixtureUserMessageBitWriter::GetNumBitsLeft() const noexcept {
			return g_nFixtureUserMessageRemainingBits;
		}

		bool FixtureUserMessageBitWriter::IsOverflowed() const noexcept {
			return g_bFixtureUserMessageOverflowed;
		}

