		constexpr int kFixtureRepeatedCapacity = 4;
		constexpr FixtureRepeatedEnumValue kFixtureRepeatedEnumValues[] = { { 0 }, { 1 }, { 73 } };

		std::array<double, kFixtureRepeatedCapacity> g_arrFixtureRepeatedValues {};
		int g_nFixtureRepeatedCount = 1;
		unsigned int g_unFixtureRepeatedWriteCalls = 0;
		unsigned int g_unFixtureRepeatedFieldSizeReads = 0;
		int g_nFixtureRepeatedLastIndex = -1;
		double g_dblFixtureRepeatedLastValue = 0.0;
		bool g_bFixtureRepeatedLastAdd = false;
		bool g_bFixtureRepeatedLastScalar = false;
