		void ResetFixtureRepeatedMessageCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr char kCountErrorMessage[] = "Controlled repeated-field count must be an integer within capacity.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if ((CallbackInformation.Length() != 1) || !CallbackInformation[0]->IsInt32()) {
				ThrowError(pIsolate, kCountErrorMessage);
				return;
			}

			const int nCount = CallbackInformation[0].As<v8::Int32>()->Value();
			if ((nCount < 0) || (nCount > kFixtureRepeatedCapacity)) {
				ThrowError(pIsolate, kCountErrorMessage);
				return;
			}

			g_nFixtureRepeatedCount = nCount;
			g_unFixtureRepeatedWriteCalls = 0;
			g_unFixtureRepeatedFieldSizeReads = 0;
			g_nFixtureRepeatedLastIndex = -1;
			g_dblFixtureRepeatedLastValue = 0.0;
			g_bFixtureRepeatedLastAdd = false;
			g_bFixtureRepeatedLastScalar = false;
			g_arrFixtureRepeatedValues.fill(0.0);
			CallbackInformation.GetReturnValue().Set(true);
		}

		void ReadFixtureRepeatedStateCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr char kBindingErrorMessage[] = "Invalid controlled repeated-field state binding.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!CallbackInformation.Data()->IsInt32()) {
				ThrowError(pIsolate, kBindingErrorMessage);
				return;
			}

			const FixtureRepeatedStateField Field = static_cast<FixtureRepeatedStateField>(CallbackInformation.Data().As<v8::Int32>()->Value());
			switch (Field) {
				case FixtureRepeatedStateField::Count:
					CallbackInformation.GetReturnValue().Set(g_nFixtureRepeatedCount);
					return;

				case FixtureRepeatedStateField::WriteCalls:
					CallbackInformation.GetReturnValue().Set(g_unFixtureRepeatedWriteCalls);
					return;

				case FixtureRepeatedStateField::FieldSizeReads:
					CallbackInformation.GetReturnValue().Set(g_unFixtureRepeatedFieldSizeReads);
					return;

				case FixtureRepeatedStateField::LastIndex:
					CallbackInformation.GetReturnValue().Set(g_nFixtureRepeatedLastIndex);
					return;

				case FixtureRepeatedStateField::LastValue:
					CallbackInformation.GetReturnValue().Set(g_dblFixtureRepeatedLastValue);
					return;

				case FixtureRepeatedStateField::LastAdd:
					CallbackInformation.GetReturnValue().Set(g_bFixtureRepeatedLastAdd);
					return;

				case FixtureRepeatedStateField::LastScalar:
					CallbackInformation.GetReturnValue().Set(g_bFixtureRepeatedLastScalar);
					return;

				default:
					ThrowError(pIsolate, kBindingErrorMessage);
					return;
			}
		}

