		void GetFixtureTransmitArrayCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr int kBitArrayKind = 0;
			constexpr int kIntegerArrayKind = 1;
			constexpr int kFixtureBufferCount = 3;

			static_assert((sizeof(g_arrFixtureTransmitIntegers) / sizeof(g_arrFixtureTransmitIntegers[0])) == static_cast<std::size_t>(kFixtureBufferCount), "Controlled integer-buffer count must match its storage.");
			static_assert((sizeof(g_arrFixtureTransmitBytes) / sizeof(g_arrFixtureTransmitBytes[0])) == static_cast<std::size_t>(kFixtureBufferCount), "Controlled byte-buffer count must match its storage.");

			auto* const pIsolate = CallbackInformation.GetIsolate();
			try {
				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				const int nKind = CallbackInformation.Data()->Int32Value(LocalContext).FromMaybe(-1);
				v8::Local<v8::Array> LocalResult {};
				if (nKind == kBitArrayKind) {
					LocalResult = MakeEngineEntityIndexArrayFromBitVector(pIsolate, LocalContext, &GetFixtureTransmitBits());

				} else if (nKind == kIntegerArrayKind) {
					LocalResult = MakeEngineIntegerArrayFromBuffer(pIsolate, LocalContext, g_arrFixtureTransmitIntegers, kFixtureBufferCount);

				} else {
					LocalResult = MakeEngineByteArrayFromBuffer(pIsolate, LocalContext, g_arrFixtureTransmitBytes, kFixtureBufferCount);
				}

				if (!LocalResult.IsEmpty()) {
					CallbackInformation.GetReturnValue().Set(LocalResult);
				}
			} catch (...) {
				ThrowError(pIsolate, "Fixture transmit-array native failure");
			}
		}

