		void MessagePlayerInstallationProbeCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr int kUncommittedPlayerIndex = 777;
			constexpr int kValidatedPlayerIndex = 4;

			auto* const pIsolate = CallbackInformation.GetIsolate();
			int nPlayerIndex = kUncommittedPlayerIndex;

			try {
				auto* const pEdict = RequireMessagePlayerEdict(pIsolate, pIsolate->GetCurrentContext(), CallbackInformation[0], "Fixture messages player", &nPlayerIndex);
				if (!pEdict) {
					Require(nPlayerIndex == kUncommittedPlayerIndex, "Do not commit a rejected message player index");
					return;
				}

				Require(nPlayerIndex == kValidatedPlayerIndex, "Commit the validated message player index");
				CallbackInformation.GetReturnValue().Set(nPlayerIndex);
			} catch (...) {
				Require(nPlayerIndex == kUncommittedPlayerIndex, "Do not commit message player output during native unwinding");
				ThrowError(pIsolate, "Fixture message player native failure.");
			}
		}

		void MessagePropertyInstallationProbeCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr int kInitialPropertyValue = 99;

			auto* const pIsolate = CallbackInformation.GetIsolate();
			v8::Local<v8::Value> const LocalOriginal = v8::Integer::New(pIsolate, kInitialPropertyValue);
			v8::Local<v8::Value> LocalOutput = LocalOriginal;

			try {
				Require(CallbackInformation[0]->IsObject(), "Supply a property-owner object");

				if (!GetMessagesObjectValue(pIsolate, pIsolate->GetCurrentContext(), CallbackInformation[0].As<v8::Object>(), "Value", "Fixture message property read failed.", LocalOutput)) {
					Require(LocalOutput->StrictEquals(LocalOriginal), "Do not commit a rejected message property output");
					return;
				}

				CallbackInformation.GetReturnValue().Set(LocalOutput);
			} catch (...) {
				Require(LocalOutput->StrictEquals(LocalOriginal), "Do not commit a message property output during native unwinding");
				ThrowError(pIsolate, "Fixture message property native failure.");
			}
		}

