		// This adapter isolates private FireGameEvent; public callback probes are separate.
		void FireGameEventProbeCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) try {
			constexpr int kPayloadArgumentIndex = 0;
			constexpr int kNameArgumentIndex = 1;
			constexpr int kBroadcastArgumentIndex = 2;

			auto* const pIsolate = CallbackInformation.GetIsolate();
			v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
			std::string strName = "FixtureEvent";
			if ((CallbackInformation.Length() > kNameArgumentIndex) && !RequireEventStringFromValue(pIsolate, CallbackInformation[kNameArgumentIndex], "Fixture name must be a string.", true, strName)) {
				return;
			}

			v8::Local<v8::Value> const LocalPayload = (CallbackInformation.Length() > kPayloadArgumentIndex) ? CallbackInformation[kPayloadArgumentIndex] : v8::Undefined(pIsolate).As<v8::Value>();
			const bool bDoNotBroadcast = (CallbackInformation.Length() > kBroadcastArgumentIndex) && CallbackInformation[kBroadcastArgumentIndex]->BooleanValue(pIsolate);
			CallbackInformation.GetReturnValue().Set(FireGameEvent(pIsolate, LocalContext, strName, LocalPayload, bDoNotBroadcast));
		} catch (...) {
			ThrowError(CallbackInformation.GetIsolate(), "Fixture FireGameEvent failed with a C++ exception.");
		}

		void EventBackendCallsProbeCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			CallbackInformation.GetReturnValue().Set(g_unBackendCalls);
		}

		// This adapter isolates private default/copy helpers; public callback probes are separate.
		void EventPayloadDefaultsProbeCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) try {
			constexpr int kVariablesArgumentIndex = 0;
			constexpr int kOverridesArgumentIndex = 1;

			auto* const pIsolate = CallbackInformation.GetIsolate();
			v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();

			if ((CallbackInformation.Length() <= kOverridesArgumentIndex) || !CallbackInformation[kVariablesArgumentIndex]->IsObject() || !CallbackInformation[kOverridesArgumentIndex]->IsObject()) {
				ThrowError(pIsolate, "Fixture payload inputs must be objects.");
				return;
			}

			v8::Local<v8::Object> const LocalPayload = v8::Object::New(pIsolate);
			if (!AddEventPayloadDefaults(pIsolate, LocalContext, LocalPayload, CallbackInformation[kVariablesArgumentIndex].As<v8::Object>()) || !CopyEventObjectProperties(pIsolate, LocalContext, LocalPayload, CallbackInformation[kOverridesArgumentIndex].As<v8::Object>())) {
				return;
			}

			CallbackInformation.GetReturnValue().Set(LocalPayload);
		} catch (...) {
			ThrowError(CallbackInformation.GetIsolate(), "Fixture event payload defaults failed with a C++ exception.");
		}

		// This adapter isolates private resource helpers; public callback probes are separate.
		void EventHelperProbeCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) try {
			constexpr int kInputArgumentIndex = 0;
			constexpr int kAllowEmptyArgumentIndex = 1;
			constexpr char kStringError[] = "Fixture event input must be a string.";
			constexpr char kObjectError[] = "Fixture event input must be an object.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
			v8::Local<v8::Value> const LocalInput = (CallbackInformation.Length() > kInputArgumentIndex) ? CallbackInformation[kInputArgumentIndex] : v8::Undefined(pIsolate).As<v8::Value>();
			// Fixture registration supplies only enum selectors as immutable Int32 callback data.
			const EventHelperKind Kind = static_cast<EventHelperKind>(CallbackInformation.Data().As<v8::Int32>()->Value());
			switch (Kind) {
				case EventHelperKind::Property: {
					if (!LocalInput->IsObject()) {
						ThrowError(pIsolate, kObjectError);
						return;
					}

					v8::Local<v8::Value> LocalValue = v8::Int32::New(pIsolate, kEventOutputSentinelValue);
					if (!GetObjectValue(pIsolate, LocalContext, LocalInput.As<v8::Object>(), "Type", LocalValue)) {
						CallbackInformation.GetReturnValue().Set(false);
						return;
					}

					CallbackInformation.GetReturnValue().Set(LocalValue);
					return;
				}

				case EventHelperKind::String: {
					std::string strValue {};
					const bool bAllowEmpty = (CallbackInformation.Length() > kAllowEmptyArgumentIndex) && CallbackInformation[kAllowEmptyArgumentIndex]->BooleanValue(pIsolate);
					if (!RequireEventStringFromValue(pIsolate, LocalInput, kStringError, bAllowEmpty, strValue)) {
						return;
					}

					CallbackInformation.GetReturnValue().Set(MakeString(pIsolate, strValue));
					return;
				}

				case EventHelperKind::Definition: {
					std::string const strType = GetEventVariableTypeFromDefinition(pIsolate, LocalContext, LocalInput);
					if (pIsolate->HasPendingException()) {
						return;
					}

					CallbackInformation.GetReturnValue().Set(MakeString(pIsolate, strType));
					return;
				}

				case EventHelperKind::Resource: {
					std::string const strText = BuildEventResourceText(pIsolate, LocalContext, "FixtureEvent", LocalInput);
					if (pIsolate->HasPendingException()) {
						return;
					}

					CallbackInformation.GetReturnValue().Set(MakeString(pIsolate, strText));
					return;
				}

				case EventHelperKind::Object: {
					v8::Local<v8::Object> LocalObject {};
					if (!RequireEventObjectFromValue(pIsolate, LocalInput, kObjectError, LocalObject)) {
						return;
					}

					CallbackInformation.GetReturnValue().Set(LocalObject);
					return;
				}
			}
		} catch (...) {
			ThrowError(CallbackInformation.GetIsolate(), "Fixture event helper failed with a C++ exception.");
		}

		void ReadCommandNameProbeCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) try {
			constexpr int kNameArgumentIndex = 0;
			constexpr char kInitialOutput[] = "Unchanged";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			std::string strCommandName = kInitialOutput;
			const bool bRead = ReadCommandName(CallbackInformation, kNameArgumentIndex, strCommandName);
			g_bCommandNameOutputUnchanged = !bRead && (strCommandName == kInitialOutput);

			if (!bRead) {
				return;
			}

			CallbackInformation.GetReturnValue().Set(MakeString(pIsolate, strCommandName));
		} catch (...) {
			constexpr char kCallbackExceptionError[] = "Command name probe failed with a C++ exception.";

			ThrowError(CallbackInformation.GetIsolate(), kCallbackExceptionError);
		}

		void CheckError(v8::Isolate* const pIsolate, fnThrowBindingError const Throw, char const* const pszExpectedName) {
			constexpr char kMessage[] = "Native binding failure: \xD0\x90";
			constexpr char kNameProperty[] = "name";
			constexpr char kMessageProperty[] = "message";

			const unsigned int unPreviousCalls = g_unMessageCalls;
			Throw(nullptr, kMessage);
			Require(g_unMessageCalls == unPreviousCalls, "Reject a null isolate before string construction");

			v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
			for (auto const& pszMessage : { kMessage, static_cast<char const*>(nullptr) }) {
				v8::TryCatch Failure(pIsolate);
				Throw(pIsolate, pszMessage);
				Require(Failure.HasCaught() && !Failure.HasTerminated(), "Catch real native error");
				Require(Failure.Exception()->IsNativeError(), "Preserve native error class");
				v8::Local<v8::Object> const LocalError = Failure.Exception().As<v8::Object>();
				v8::Local<v8::Value> LocalName {};
				v8::Local<v8::Value> LocalMessage {};
				Require(LocalError->Get(LocalContext, v8::String::NewFromUtf8(pIsolate, kNameProperty).ToLocalChecked()).ToLocal(&LocalName), "Read error name");
				Require(LocalError->Get(LocalContext, v8::String::NewFromUtf8(pIsolate, kMessageProperty).ToLocalChecked()).ToLocal(&LocalMessage), "Read error message");
				v8::String::Utf8Value const UTF8Name(pIsolate, LocalName);
				v8::String::Utf8Value const UTF8Message(pIsolate, LocalMessage);
				Require(*UTF8Name && (std::string(*UTF8Name) == pszExpectedName), "Preserve Error versus TypeError");
				Require(*UTF8Message && (std::string(*UTF8Message) == (pszMessage ? pszMessage : "")), "Preserve UTF8 and null-message semantics");
			}

			{
				v8::TryCatch Failure(pIsolate);
				v8::Local<v8::Object> const LocalOriginal = v8::Object::New(pIsolate);
				pIsolate->ThrowException(LocalOriginal);
				const unsigned int unCallsBeforePending = g_unMessageCalls;
				Throw(pIsolate, kMessage);
				Require(Failure.HasCaught() && (Failure.Exception() == LocalOriginal), "Preserve an existing exception identity");
				Require(g_unMessageCalls == unCallsBeforePending, "Do not allocate an error message while an exception is pending");
			}

			{
				v8::TryCatch Failure(pIsolate);
				g_MessageFault = MessageFault::Empty;
				Throw(pIsolate, kMessage);
				g_MessageFault = MessageFault::None;
				Require(Failure.HasCaught() && Failure.Exception()->IsUndefined(), "Empty message handle throws V8's undefined fallback");
			}

			{
				v8::TryCatch Failure(pIsolate);
				g_MessageFault = MessageFault::PendingException;
				Throw(pIsolate, kMessage);
				g_MessageFault = MessageFault::None;
				Require(Failure.HasCaught() && Failure.Exception()->IsTrue(), "Preserve an exception raised during message construction");
			}

			{
				v8::TryCatch Failure(pIsolate);
				TerminateScript(pIsolate);
				const unsigned int unCallsBeforeTermination = g_unMessageCalls;
				Throw(pIsolate, kMessage);
				const bool bTerminated = Failure.HasTerminated() && pIsolate->IsExecutionTerminating();
				pIsolate->CancelTerminateExecution();
				Require(bTerminated && (g_unMessageCalls == unCallsBeforeTermination), "Do not allocate or replace execution termination");
			}

			{
				v8::TryCatch Failure(pIsolate);
				g_MessageFault = MessageFault::Termination;
				Throw(pIsolate, kMessage);
				g_MessageFault = MessageFault::None;
				const bool bTerminated = Failure.HasTerminated() && pIsolate->IsExecutionTerminating();
				pIsolate->CancelTerminateExecution();
				Require(bTerminated, "Preserve termination raised during message construction");
			}
		}

		v8::Local<v8::Value> Evaluate(v8::Isolate* const pIsolate, char const* const pszSource) {
			v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
			v8::Local<v8::Script> LocalScript {};
			Require(v8::Script::Compile(LocalContext, MakeString(pIsolate, pszSource)).ToLocal(&LocalScript), "Compile fixture JavaScript");
			v8::Local<v8::Value> LocalResult {};
			Require(LocalScript->Run(LocalContext).ToLocal(&LocalResult), "Evaluate fixture JavaScript");

			return LocalResult;
		}

		void CheckRequiredVectors(v8::Isolate* const pIsolate) {
			// Fully initialized test vectors retain the SDK Vector field spelling at the native boundary.
			struct VectorCase {
				char const* m_pszSource;
				float m_flX;
				float m_flY;
				float m_flZ;
			};

			constexpr float kUncommittedX = 11.0F;
			constexpr float kUncommittedY = 12.0F;
			constexpr float kUncommittedZ = 13.0F;
			constexpr char kErrorMessage[] = "Required vector expects finite numeric components.";
			constexpr char const* kInvalidSources[] = { "null", "undefined", "1", "{}", "[]", "({ X: Infinity })", "[1, NaN, 3]", "[1, 1e100, 3]" };
			constexpr VectorCase kValidCases[] = {
				{ "[1, 2, 3]", 1.0F, 2.0F, 3.0F },
				{ "({ X: 1, Y: 2, Z: 3 })", 1.0F, 2.0F, 3.0F },
				{ "({ Pitch: 4, Yaw: 5, Roll: 6 })", 4.0F, 5.0F, 6.0F },
				{ "[undefined, 2, null]", 0.0F, 2.0F, 0.0F },
				{ "({ X: 0 })", 0.0F, 0.0F, 0.0F },
				{ "['1', '2', '3']", 1.0F, 2.0F, 3.0F },
			};

			v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
			for (auto const& pszSource : kInvalidSources) {
				Vector Output {};
				Output.Init(kUncommittedX, kUncommittedY, kUncommittedZ);
				v8::Local<v8::Value> const LocalInput = Evaluate(pIsolate, pszSource);
				v8::TryCatch Failure(pIsolate);
				Require(!RequireVectorFromValue(pIsolate, LocalContext, LocalInput, kErrorMessage, Output) && Failure.HasCaught(), "Reject missing or invalid required vector");
				Require((Output.x == kUncommittedX) && (Output.y == kUncommittedY) && (Output.z == kUncommittedZ), "Failed required vector preserves every output component");
			}

			for (auto const& Case : kValidCases) {
				Vector Output {};
				Output.Init(kUncommittedX, kUncommittedY, kUncommittedZ);
				v8::Local<v8::Value> const LocalInput = Evaluate(pIsolate, Case.m_pszSource);
				Require(RequireVectorFromValue(pIsolate, LocalContext, LocalInput, kErrorMessage, Output), "Accept valid required vector");
				Require((Output.x == Case.m_flX) && (Output.y == Case.m_flY) && (Output.z == Case.m_flZ), "Commit every valid vector component");
			}

			v8::Local<v8::Object> const LocalMarker = v8::Object::New(pIsolate);
			Require(LocalContext->Global()->Set(LocalContext, MakeString(pIsolate, "VectorMarker"), LocalMarker).FromMaybe(false), "Install getter failure marker");
			v8::Local<v8::Value> const LocalInput = Evaluate(pIsolate, "({ X: 1, get Y() { throw globalThis.VectorMarker; }, Z: 3 })");
			Vector Output {};
			Output.Init(kUncommittedX, kUncommittedY, kUncommittedZ);
			v8::TryCatch Failure(pIsolate);
			Require(!RequireVectorFromValue(pIsolate, LocalContext, LocalInput, kErrorMessage, Output), "Reject throwing component getter");
			Require(Failure.HasCaught() && (Failure.Exception() == LocalMarker), "Preserve vector getter exception identity");
			Require((Output.x == kUncommittedX) && (Output.y == kUncommittedY) && (Output.z == kUncommittedZ), "Getter failure must not commit a partial vector");
		}

		v8::Local<v8::Value> ReadRecordValue(v8::Isolate* const pIsolate, v8::Local<v8::Object> const LocalRecord, char const* const pszName) {
			v8::Local<v8::Value> LocalValue {};
			Require(LocalRecord->Get(pIsolate->GetCurrentContext(), MakeString(pIsolate, pszName)).ToLocal(&LocalValue), "Read native record property");

			return LocalValue;
		}

		void CheckEntityRecords(v8::Isolate* const pIsolate) {
			constexpr unsigned int kHandleValues[] = { 0, 1, 0x80000000, 0xFFFFFFFE, 0xFFFFFFFF };
			constexpr char kHandleContract[] = "(Object.keys(HandleRecord).join(',') === 'Kind,Value,EntryIndex,SerialNumber,Valid') && (HandleRecord.Kind === 'basehandle') && (typeof HandleRecord.Value === 'number') && (typeof HandleRecord.EntryIndex === 'number') && (typeof HandleRecord.SerialNumber === 'number') && (typeof HandleRecord.Valid === 'boolean')";
			constexpr char kAddressContract[] = "(Object.keys(AddressRecord).join(',') === 'Kind,Address,Index,ClassName') && (AddressRecord.Kind === 'edict') && (typeof AddressRecord.Address === 'bigint') && (AddressRecord.Index === -1) && (AddressRecord.ClassName === '')";

			v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
			for (auto const& unValue : kHandleValues) {
				CBaseHandle const EntityHandle { unValue };
				v8::Local<v8::Object> const LocalRecord = MakeEntityBaseHandleObject(pIsolate, LocalContext, EntityHandle);
				Require(!LocalRecord.IsEmpty(), "Construct handle record");
				Require(SetValue(pIsolate, LocalContext, LocalContext->Global(), "HandleRecord", LocalRecord), "Publish handle record probe");
				Require(Evaluate(pIsolate, kHandleContract)->IsTrue(), "Preserve PascalCase handle keys and property types");
				v8::Local<v8::Value> const LocalValue = ReadRecordValue(pIsolate, LocalRecord, "Value");
				Require(LocalValue->IsUint32() && (LocalValue.As<v8::Uint32>()->Value() == unValue), "Preserve the full unsigned 32-bit handle");
				Require(ReadRecordValue(pIsolate, LocalRecord, "Valid")->BooleanValue(pIsolate) == EntityHandle.IsValid(), "Preserve SDK validity, including zero and the invalid sentinel");
				v8::Local<v8::Value> const LocalEntryIndex = ReadRecordValue(pIsolate, LocalRecord, "EntryIndex");
				Require(LocalEntryIndex->IsInt32() && (LocalEntryIndex.As<v8::Int32>()->Value() == EntityHandle.GetEntryIndex()), "Preserve entry index");
				v8::Local<v8::Value> const LocalSerialNumber = ReadRecordValue(pIsolate, LocalRecord, "SerialNumber");
				Require(LocalSerialNumber->IsInt32() && (LocalSerialNumber.As<v8::Int32>()->Value() == EntityHandle.GetSerialNumber()), "Preserve serial number");
			}

			CBaseHandle HandleStorage {};
			for (auto const& pAddress : { static_cast<void*>(nullptr), static_cast<void*>(&HandleStorage) }) {
				v8::Local<v8::Object> const LocalRecord = MakeEntityAddressObject(pIsolate, LocalContext, "edict", pAddress, -1, nullptr);
				Require(!LocalRecord.IsEmpty(), "Construct address record");
				Require(SetValue(pIsolate, LocalContext, LocalContext->Global(), "AddressRecord", LocalRecord), "Publish address record probe");
				Require(Evaluate(pIsolate, kAddressContract)->IsTrue(), "Preserve PascalCase address keys and BigInt type");
				v8::Local<v8::Value> const LocalAddress = ReadRecordValue(pIsolate, LocalRecord, "Address");
				bool bLossless = false;
				const std::uint64_t unAddress = LocalAddress.As<v8::BigInt>()->Uint64Value(&bLossless);
				Require(bLossless && (unAddress == static_cast<std::uint64_t>(reinterpret_cast<std::uintptr_t>(pAddress))), "Preserve exact null/borrowed address bits");
			}

			Require(MakeEntityBaseHandleObject(nullptr, LocalContext, HandleStorage).IsEmpty(), "Reject null isolate");
			Require(MakeEntityBaseHandleObject(pIsolate, {}, HandleStorage).IsEmpty(), "Reject empty context");
			g_MessageFault = MessageFault::Empty;
			v8::Local<v8::Object> const LocalFailedRecord = MakeEntityBaseHandleObject(pIsolate, LocalContext, HandleStorage);
			g_MessageFault = MessageFault::None;
			Require(LocalFailedRecord.IsEmpty(), "Do not return a partially initialized record after string failure");
		}

		constexpr char kFixtureRecordClassBefore[] = "fixture_before";
		constexpr char kFixtureRecordClassAfter[] = "fixture_after_";

		static_assert(sizeof(kFixtureRecordClassBefore) == sizeof(kFixtureRecordClassAfter), "Record mutation storage must remain readable with equal string extents.");

		char g_szFixtureRecordClass[sizeof(kFixtureRecordClassBefore)] {};
		int g_nFixtureRecordAddressOwner = 0;
		bool g_bLastFixtureRecordResultEmpty = false;

		void ResetFixtureEntityRecordCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			std::copy_n(kFixtureRecordClassBefore, sizeof(kFixtureRecordClassBefore), g_szFixtureRecordClass);
			g_bLastFixtureRecordResultEmpty = false;
			CallbackInformation.GetReturnValue().Set(v8::BigInt::NewFromUnsigned(CallbackInformation.GetIsolate(), reinterpret_cast<std::uintptr_t>(&g_nFixtureRecordAddressOwner)));
		}

		void MutateFixtureEntityRecordClassCallback(v8::FunctionCallbackInfo<v8::Value> const&) {
			std::copy_n(kFixtureRecordClassAfter, sizeof(kFixtureRecordClassAfter), g_szFixtureRecordClass);
		}

		void GetFixtureEntityRecordCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr int kFixtureEntityRecordIndex = 4;

			auto* const pIsolate = CallbackInformation.GetIsolate();
			try {
				v8::Local<v8::Object> const LocalRecord = MakeEntityAddressObject(pIsolate, pIsolate->GetCurrentContext(), "edict", &g_nFixtureRecordAddressOwner, kFixtureEntityRecordIndex, g_szFixtureRecordClass);
				g_bLastFixtureRecordResultEmpty = LocalRecord.IsEmpty();
				if (!LocalRecord.IsEmpty()) {
					CallbackInformation.GetReturnValue().Set(LocalRecord);
				}
			} catch (...) {
				g_bLastFixtureRecordResultEmpty = true;
				ThrowError(pIsolate, "Controlled entity record snapshot failed with a native C++ exception.");
			}
		}

		void GetFixtureEntityHandleRecordCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr unsigned int kFixtureHandleValue = 0x80000001;

			auto* const pIsolate = CallbackInformation.GetIsolate();
			try {
				CBaseHandle const Handle { kFixtureHandleValue };
				v8::Local<v8::Object> const LocalRecord = MakeEntityBaseHandleObject(pIsolate, pIsolate->GetCurrentContext(), Handle);
				g_bLastFixtureRecordResultEmpty = LocalRecord.IsEmpty();
				if (!LocalRecord.IsEmpty()) {
					CallbackInformation.GetReturnValue().Set(LocalRecord);
				}
			} catch (...) {
				g_bLastFixtureRecordResultEmpty = true;
				ThrowError(pIsolate, "Controlled entity handle record failed with a native C++ exception.");
			}
		}

		void SetFixtureEntityRecordPropertyFailureCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			g_bFixtureEntityRecordPropertyFailure = (CallbackInformation.Length() > 0) && CallbackInformation[0]->IsTrue();
			CallbackInformation.GetReturnValue().Set(g_bFixtureEntityRecordPropertyFailure);
		}

		void SetFixtureEngineAddressPropertyHookCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			g_bFixtureEngineAddressPropertyHook = (CallbackInformation.Length() > 0) && CallbackInformation[0]->IsTrue();
			CallbackInformation.GetReturnValue().Set(g_bFixtureEngineAddressPropertyHook);
		}

		void IsFixtureEntityRecordEmptyCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			CallbackInformation.GetReturnValue().Set(g_bLastFixtureRecordResultEmpty);
		}

		void CheckEntityRecordStringSnapshots(v8::Isolate* const pIsolate) {
			struct CallbackBinding {
				char const* m_pszName;
				v8::FunctionCallback m_Callback;
			};

			constexpr CallbackBinding kBindings[] = {
				{ "FixtureResetEntityRecord", ResetFixtureEntityRecordCallback },
				{ "FixtureMutateEntityClass", MutateFixtureEntityRecordClassCallback },
				{ "FixtureEntityRecord", GetFixtureEntityRecordCallback },
				{ "FixtureEntityHandleRecord", GetFixtureEntityHandleRecordCallback },
				{ "FixtureSetEntityRecordPropertyFailure", SetFixtureEntityRecordPropertyFailureCallback },
				{ "FixtureEntityRecordWasEmpty", IsFixtureEntityRecordEmptyCallback },
			};

			v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
			for (auto const& Binding : kBindings) {
				v8::Local<v8::Function> LocalCallback {};
				Require(v8::Function::New(LocalContext, Binding.m_Callback).ToLocal(&LocalCallback) && SetRecordProperty(pIsolate, LocalContext, LocalContext->Global(), Binding.m_pszName, LocalCallback), "Publish entity record snapshot probes");
			}

			v8::Local<v8::Value> const LocalResult = Evaluate(pIsolate, R"((() => {
				const vecRecordProbes = [
					{ Create: FixtureEntityRecord, Fields: ["Kind", "Address", "Index", "ClassName"] },
					{ Create: FixtureEntityHandleRecord, Fields: ["Kind", "Value", "EntryIndex", "SerialNumber", "Valid"] },
				];
				const Original = new Error("Inherited entity record property");
				const Restore = (strName, Descriptor) => {
					if (Descriptor === undefined) {
						delete Object.prototype[strName];
					} else {
						Object.defineProperty(Object.prototype, strName, Descriptor);
					}
				};

				let unBaselineCases = 0;
				let unOwnPropertyCases = 0;
				for (const Probe of vecRecordProbes) {
					FixtureResetEntityRecord();
					const Expected = Probe.Create();
					if ((Expected === null) || (typeof Expected !== "object") || (Object.keys(Expected).join(",") !== Probe.Fields.join(","))) {
						return "BaselineFields";
					}

					++unBaselineCases;

					for (const strName of Probe.Fields) {
						for (const bAccessor of [true, false]) {
							FixtureResetEntityRecord();
							const Descriptor = Object.getOwnPropertyDescriptor(Object.prototype, strName);
							let unInheritedCalls = 0;
							let Record = null;
							Object.defineProperty(Object.prototype, strName, bAccessor
								? { configurable: true, get() { ++unInheritedCalls; throw Original; }, set() { ++unInheritedCalls; FixtureMutateEntityClass(); throw Original; } }
								: { configurable: true, writable: false, value: Original });

							try {
								Record = Probe.Create();
							} catch {
								return "InheritedException Field=" + strName;
							} finally {
								Restore(strName, Descriptor);
							}

							if ((unInheritedCalls !== 0) || FixtureEntityRecordWasEmpty() || (Record === null) || (typeof Record !== "object") || (Object.keys(Record).join(",") !== Probe.Fields.join(","))) {
								return "OwnFields Field=" + strName;
							}

							for (const strField of Probe.Fields) {
								const FieldDescriptor = Object.getOwnPropertyDescriptor(Record, strField);
								if ((FieldDescriptor === undefined) || !Object.hasOwn(FieldDescriptor, "value") || !FieldDescriptor.writable || !FieldDescriptor.enumerable || !FieldDescriptor.configurable || (FieldDescriptor.value !== Expected[strField])) {
									return "OwnDescriptor Field=" + strField;
								}
							}

							++unOwnPropertyCases;
						}
					}
				}

				if ((unBaselineCases !== 2) || (unOwnPropertyCases !== 18)) {
					return "MissingOwnPropertyCases";
				}

				FixtureResetEntityRecord();
				const Snapshot = FixtureEntityRecord();
				FixtureMutateEntityClass();
				if (Snapshot.ClassName !== "fixture_before") {
					return "BorrowedStringSnapshot";
				}

				for (const Create of [FixtureEntityRecord, FixtureEntityHandleRecord]) {
					FixtureResetEntityRecord();
					FixtureSetEntityRecordPropertyFailure(true);
					let bOriginalError = false;
					try {
						Create();
					} catch (ErrorValue) {
						bOriginalError = ErrorValue === false;
					} finally {
						FixtureSetEntityRecordPropertyFailure(false);
					}

					if (!bOriginalError || !FixtureEntityRecordWasEmpty()) {
						return "PropertyFailureOrPartialRecord";
					}
				}

				return true;
			})())");
			if (!LocalResult->IsTrue()) {
				std::string const strFailure = ValueToString(pIsolate, LocalResult);
				throw std::runtime_error("Initialize entity records with own data properties: " + strFailure);
			}
		}

		void CheckNativeExpression(v8::Isolate* const pIsolate, char const* const pszSource, char const* const pszExpectedSource, char const* const pszOperation, const unsigned int unSuccessCalls = 1, const unsigned int unFaultCall = 1) {
			v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
			v8::Local<v8::Value> const LocalExpected = Evaluate(pIsolate, pszExpectedSource);
			v8::Local<v8::Script> LocalScript {};
			Require(v8::Script::Compile(LocalContext, MakeString(pIsolate, pszSource)).ToLocal(&LocalScript), "Compile native callback/property invocation");

			for (auto const& Fault : { BackendFault::None, BackendFault::RuntimeError, BackendFault::BadAllocation, BackendFault::Unknown, BackendFault::PendingException }) {
				g_BackendFault = Fault;
				g_unBackendCalls = 0;
				g_unBackendFaultCall = unFaultCall;
				g_unServerCommandCalls = 0;

				v8::TryCatch Failure(pIsolate);
				v8::Local<v8::Value> LocalResult {};
				const bool bCompleted = LocalScript->Run(LocalContext).ToLocal(&LocalResult);
				g_BackendFault = BackendFault::None;
				g_unBackendFaultCall = 1;
				const unsigned int unExpectedCalls = (Fault == BackendFault::None) ? unSuccessCalls : unFaultCall;
				if (g_unBackendCalls != unExpectedCalls) {
					std::string const strFailure = std::string("Preserve native dispatch count and stop at the selected fault Operation=") + pszOperation + " Expected=" + std::to_string(unExpectedCalls) + " Actual=" + std::to_string(g_unBackendCalls);
					throw std::runtime_error(strFailure);
				}

				if (Fault == BackendFault::None) {
					Require(bCompleted && !Failure.HasCaught(), "Preserve successful native callback execution");
					std::string const strResultFailure = std::string("Preserve native callback/property result and type Operation=") + pszOperation;
					Require(LocalResult->StrictEquals(LocalExpected), strResultFailure.c_str());
					continue;
				}

				Require(!bCompleted && Failure.HasCaught() && !Failure.HasTerminated(), "Translate C++ exceptions at the real V8 callback boundary");

				if (Fault == BackendFault::PendingException) {
					Require(Failure.Exception()->IsTrue(), "Preserve the existing JavaScript exception after native unwinding");
					continue;
				}

				Require(Failure.Exception()->IsNativeError(), "Translate native failures into Error");
				v8::Local<v8::Value> LocalMessage {};
				Require(Failure.Exception().As<v8::Object>()->Get(LocalContext, MakeString(pIsolate, "message")).ToLocal(&LocalMessage), "Read translated callback error message");
				std::string const strExpectedMessage = std::string(pszOperation) + " failed because a native C++ exception occurred.";
				Require(ValueToString(pIsolate, LocalMessage) == strExpectedMessage, "Preserve callback diagnostic context");
			}
		}

		void CheckNativeCallback(v8::Isolate* const pIsolate, v8::FunctionCallback const Callback, char const* const pszOperation, char const* const pszArguments, const bool bIndexResult, const bool bClient = false, char const* const pszExpectedString = nullptr) {
			constexpr int kEntityCallbackIndex = 4;

			v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
			v8::Local<v8::Function> LocalCallback {};
			Require(v8::Function::New(LocalContext, Callback, v8::Integer::New(pIsolate, kEntityCallbackIndex)).ToLocal(&LocalCallback), "Create actual native entity callback");
			Require(SetValue(pIsolate, LocalContext, LocalContext->Global(), "NativeEntityCallback", LocalCallback), "Register actual native entity callback");

			std::string const strSource = bClient ? (std::string("NativeEntityCallback.call({ Address: ClientAddress }, ") + pszArguments + ")") : (std::string("NativeEntityCallback(") + pszArguments + ")");
			std::string const strExpectedSource = pszExpectedString ? (std::string("'") + pszExpectedString + "'") : (bIndexResult ? "4" : "true");
			CheckNativeExpression(pIsolate, strSource.c_str(), strExpectedSource.c_str(), pszOperation);
		}

		void CheckWithoutBackend(v8::Isolate* const pIsolate, char const* const pszSource) {
			std::string const strFailureMessage = std::string("Preserve validation/JavaScript failure contract Test=") + pszSource;
			g_unBackendCalls = 0;
			g_unServerCommandCalls = 0;
			Require(Evaluate(pIsolate, pszSource)->IsTrue(), strFailureMessage.c_str());
			Require(g_unBackendCalls == 0, "Stop invalid operations before SDK dispatch");
		}

		void CheckEntityCallbacks(v8::Isolate* const pIsolate) {
			constexpr int kPlayerIndex = 4;

			CheckNativeCallback(pIsolate, PlayerGiveNamedItemMethodCallback, "Player.GiveNamedItem()", "'Item'", false);
			CheckNativeCallback(pIsolate, GiveNamedItemCallback, "players/engines.GiveNamedItem()", "4, 'Item'", false);
			CheckNativeCallback(pIsolate, GiveNamedItemEntityIndexCallback, "players/engines.GiveNamedItemIndex()", "4, 'Item'", true);
			CheckNativeCallback(pIsolate, EntitySlayMethodCallback, "Entity.SlayEntity()", "", false);
			CheckNativeCallback(pIsolate, EntityCallInputMethodCallback, "Entity.CallEntityInput()", "'Use', 7, 0", false);
			CheckNativeCallback(pIsolate, CallEntityInputCallback, "entities.CallEntityInput()", "4, 'Use', 7, 0", false);
			CheckNativeCallback(pIsolate, EntityRemoveMethodCallback, "Entity.RemoveEntity()", "", false);
			CheckNativeCallback(pIsolate, RemoveEntityCallback, "entities.RemoveEntity(Entity)", "4", false);
			CheckWithoutBackend(pIsolate, "(() => { try { NativeEntityCallback(); } catch (Failure) { return Failure instanceof Error; } return false; })()");
			CheckWithoutBackend(pIsolate, "(() => { try { NativeEntityCallback({ get Index() { throw true; } }); } catch (Failure) { return Failure === true; } return false; })()");
			g_EventCallbackFault = MessageFault::PendingCppException;
			CheckWithoutBackend(pIsolate, "(() => { try { NativeEntityCallback(4); } catch (Failure) { return Failure === true; } return false; })()");
			g_EventCallbackFault = MessageFault::None;

			CheckNativeCallback(pIsolate, PlayerExecuteClientCommandMethodCallback, "Player.ExecuteClientCommand()", "'status', false", false);
			v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
#if defined(_WIN32) || defined(__linux__)
			CheckNativeCallback(pIsolate, PlayerSlayMethodCallback, "Player.Slay()", "", false);
			v8::Local<v8::Function> LocalIgnite {};
			Require(v8::Function::New(LocalContext, PlayerIgniteMethodCallback, v8::Integer::New(pIsolate, kPlayerIndex)).ToLocal(&LocalIgnite), "Create native Player.Ignite callback");
			Require(SetValue(pIsolate, LocalContext, LocalContext->Global(), "NativeIgnite", LocalIgnite), "Register native Player.Ignite callback");
			CheckWithoutBackend(pIsolate, "(() => { try { NativeIgnite(0); } catch (Failure) { return Failure instanceof Error; } return false; })()");
#else
			v8::Local<v8::Function> LocalSlay {};
			Require(v8::Function::New(LocalContext, PlayerSlayMethodCallback, v8::Integer::New(pIsolate, kPlayerIndex)).ToLocal(&LocalSlay), "Create unsupported Player.Slay callback");
			Require(SetValue(pIsolate, LocalContext, LocalContext->Global(), "NativeSlay", LocalSlay), "Register unsupported Player.Slay callback");
			CheckWithoutBackend(pIsolate, "NativeSlay() === false");
#endif
			CheckNativeCallback(pIsolate, PlayerSayMethodCallback, "Player.Say()", "'Message'", false);
			CheckNativeCallback(pIsolate, PlayerSayTeamMethodCallback, "Player.SayTeam()", "'Message'", false);
		}

		void CheckClientAddresses(v8::Isolate* const pIsolate) {
			constexpr std::uintptr_t kExpectedAddress = 0x49;
			constexpr std::uintptr_t kUnchangedAddress = 0xA5;

			v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
			v8::Local<v8::Value> const LocalRecord = Evaluate(pIsolate, "({ Address: 0x49n })");
			std::uintptr_t unAddress = kUnchangedAddress;
			Require(GetEngineServerAddressFromValue(pIsolate, LocalContext, LocalRecord, unAddress) && (unAddress == kExpectedAddress), "Read PascalCase BigInt client address");
			Require(GetEngineServerAddressFromValue(pIsolate, LocalContext, v8::BigInt::NewFromUnsigned(pIsolate, kExpectedAddress), unAddress) && (unAddress == kExpectedAddress), "Read direct BigInt client address");

			for (auto const& pszInvalid : { "({ address: 0x49n })", "({ Address: 0x49 })", "({ Address: -1n })", "({ Address: 0x10000000000000000n })", "null", "undefined" }) {
				v8::Local<v8::Value> const LocalInvalid = Evaluate(pIsolate, pszInvalid);
				unAddress = kUnchangedAddress;
				Require(!GetEngineServerAddressFromValue(pIsolate, LocalContext, LocalInvalid, unAddress) && (unAddress == kUnchangedAddress), "Reject invalid client addresses without committing output");
			}

			unAddress = kUnchangedAddress;
			g_MessageFault = MessageFault::Empty;
			const bool bEmptyConverted = GetEngineServerAddressFromValue(pIsolate, LocalContext, LocalRecord, unAddress);
			g_MessageFault = MessageFault::None;
			Require(!bEmptyConverted && (unAddress == kUnchangedAddress), "Reject an empty property-name handle before calling V8 Get");

			v8::Local<v8::Value> const LocalThrowingRecord = Evaluate(pIsolate, "Object.defineProperty({}, 'Address', { get() { throw true; } })");
			v8::TryCatch Failure(pIsolate);
			Require(!GetEngineServerAddressFromValue(pIsolate, LocalContext, LocalThrowingRecord, unAddress) && Failure.HasCaught() && Failure.Exception()->IsTrue() && (unAddress == kUnchangedAddress), "Preserve Address getter exception and output");
		}

		void CheckClientCallbacks(v8::Isolate* const pIsolate) {
			const std::uintptr_t unClientAddress = reinterpret_cast<std::uintptr_t>(&g_Client);
			Require(SetValue(pIsolate, pIsolate->GetCurrentContext(), pIsolate->GetCurrentContext()->Global(), "ClientAddress", v8::BigInt::NewFromUnsigned(pIsolate, static_cast<std::uint64_t>(unClientAddress))), "Publish borrowed client adapter address");

			CheckNativeCallback(pIsolate, DisconnectCurrentIServerClientCallback, "engines/server Client.DisconnectClient()", "'FixtureReason'", false, true);
			CheckNativeCallback(pIsolate, ExecuteIServerClientStringCommandCallback, "engines/server Client.ExecuteClientStringCommand()", "'FixtureCommand'", false, true);
			CheckNativeCallback(pIsolate, PrintToIServerClientConsoleCallback, "engines/server Client.PrintToClientConsole()", "'FixtureMessage'", false, true);
			CheckNativeCallback(pIsolate, GetIServerClientUserSettingCallback, "engines/server Client.GetUserSetting()", "'FixtureName'", false, true, "FixtureValue");
			CheckNativeCallback(pIsolate, SetIServerClientNetworkRateCallback, "engines/server Client.SetNetworkRate()", "73, false", false, true);
			CheckNativeCallback(pIsolate, SetIServerClientUpdateRateCallback, "engines/server Client.SetUpdateRate()", "73, false", false, true);
		}

		template <typename TCreateRecord>
		v8::Local<v8::Object> CheckRecordPrototypeConstruction(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, char const* const pszFieldName, const bool bAccessor, TCreateRecord const& CreateRecord, char const* const pszFailure) {
			std::string const strSetup = std::string(R"js(
((strName, bAccessor) => {
	const Original = Object.getOwnPropertyDescriptor(Object.prototype, strName);
	let unInheritedCalls = 0;
	Object.defineProperty(Object.prototype, strName, bAccessor ? {
		configurable: true,
		get() {
			++unInheritedCalls;
			throw false;
		},
		set() {
			++unInheritedCalls;
			throw false;
		},
	} : { configurable: true, writable: false, value: false });

	return () => {
		if (Original === undefined) {
			delete Object.prototype[strName];
		} else {
			Object.defineProperty(Object.prototype, strName, Original);
		}

		return unInheritedCalls;
	};
})
)js") + "('" + pszFieldName + "', " + (bAccessor ? "true" : "false") + ");";
			v8::Local<v8::Value> const LocalRestore = Evaluate(pIsolate, strSetup.c_str());
			Require(LocalRestore->IsFunction(), "Install reversible record prototype probe");

			v8::Local<v8::Object> LocalRecord {};
			bool bCaughtFailure = false;
			{
				v8::TryCatch RecordFailure(pIsolate);
				LocalRecord = CreateRecord();
				bCaughtFailure = RecordFailure.HasCaught();
				if (bCaughtFailure) {
					RecordFailure.Reset();
				}
			}

			v8::Local<v8::Value> LocalInheritedCalls {};
			Require(LocalRestore.As<v8::Function>()->Call(LocalContext, v8::Undefined(pIsolate), 0, nullptr).ToLocal(&LocalInheritedCalls), "Restore record prototype");
			const bool bHasRecord = !bCaughtFailure && !LocalRecord.IsEmpty() && LocalInheritedCalls->IsUint32() && (LocalInheritedCalls.As<v8::Uint32>()->Value() == 0);
			Require(bHasRecord, pszFailure);

			return LocalRecord;
		}

		void CheckBindingRecordConstruction(v8::Isolate* const pIsolate) {
			struct BindingProbe {
				bool m_bCommand;
				char const* m_pszFieldName;
				bool m_bModernOnly;
			};

			constexpr BindingProbe kProbes[] = {
				{ true, "Continue", false },
				{ true, "Block", false },
				{ true, "Handled", false },
				{ true, "CONTINUE", false },
				{ true, "BLOCK", false },
				{ true, "HANDLED", false },
				{ true, "MAX_COMMAND_LENGTH", true },
				{ true, "CommandReturn", false },
				{ true, "GetCommandReturnNumber", false },
				{ true, "GetCommandReturnObject", false },
				{ false, "Pre", false },
				{ false, "Post", false },
				{ false, "PRE", false },
				{ false, "POST", false },
				{ false, "HookType", false },
			};
			constexpr std::size_t kModernProbeCount = 30;
			constexpr std::size_t kLegacyProbeCount = 28;

			v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
			Require(SetRecordProperty(pIsolate, LocalContext, LocalContext->Global(), "BindingRecordsLegacy", v8::Boolean::New(pIsolate, kFixtureLegacyBindingRecords)), "Publish binding record console profile");
			Require(SetRecordProperty(pIsolate, LocalContext, LocalContext->Global(), "BindingRecordsMaximumLength", v8::Integer::New(pIsolate, kFixtureMaximumCommandLength)), "Publish controlled SDK command limit");
			Require(SetRecordProperty(pIsolate, LocalContext, LocalContext->Global(), "BindingRecordsPre", v8::Integer::New(pIsolate, HOOKTYPE_PRE)), "Publish actual pre-hook mode");
			Require(SetRecordProperty(pIsolate, LocalContext, LocalContext->Global(), "BindingRecordsPost", v8::Integer::New(pIsolate, HOOKTYPE_POST)), "Publish actual post-hook mode");

			std::size_t unProbeCount = 0;
			for (auto const& Probe : kProbes) {
				if (Probe.m_bModernOnly && kFixtureLegacyBindingRecords) {
					continue;
				}

				for (auto const& bAccessor : { true, false }) {
					std::string const strFailure = std::string("Initialize binding records with own fields: Field=") + Probe.m_pszFieldName + (bAccessor ? " Accessor" : " NonWritable");
					auto const CreateRecord = [pIsolate, LocalContext, &Probe]() -> v8::Local<v8::Object> {
						v8::Local<v8::Object> const LocalModule = v8::Object::New(pIsolate);
						const bool bInstalled = Probe.m_bCommand ? InstallCommandReturnBindings(pIsolate, LocalContext, LocalModule) : InstallHookTypeBindings(pIsolate, LocalContext, LocalModule);
						if (!bInstalled) {
							return {};
						}

						return LocalModule;
					};
					v8::Local<v8::Object> const LocalRecord = CheckRecordPrototypeConstruction(pIsolate, LocalContext, Probe.m_pszFieldName, bAccessor, CreateRecord, strFailure.c_str());
					Require(SetRecordProperty(pIsolate, LocalContext, LocalContext->Global(), "BindingConstructionRecord", LocalRecord), "Publish native binding construction result");
					Require(SetRecordProperty(pIsolate, LocalContext, LocalContext->Global(), "BindingRecordsCommand", v8::Boolean::New(pIsolate, Probe.m_bCommand)), "Publish native binding family");
					Require(Evaluate(pIsolate, R"js(
(() => {
	const Record = BindingConstructionRecord;
	const bCommand = BindingRecordsCommand;
	const Nested = bCommand ? Record.CommandReturn : Record.HookType;
	const vecFields = bCommand ? ["CONTINUE", "BLOCK", "HANDLED", ...(BindingRecordsLegacy ? [] : ["MAX_COMMAND_LENGTH"]), "CommandReturn", "GetCommandReturnNumber", "GetCommandReturnObject"] : ["PRE", "POST", "HookType"];
	const vecNestedFields = bCommand ? ["Continue", "Block", "Handled"] : ["Pre", "Post"];
	const IsOwnData = (Value, strName) => {
		const Descriptor = Object.getOwnPropertyDescriptor(Value, strName);

		return (Descriptor !== undefined) && Object.hasOwn(Descriptor, "value") && Descriptor.writable && Descriptor.enumerable && Descriptor.configurable;
	};
	const bOwnFields = (Object.keys(Record).join(",") === vecFields.join(",")) && vecFields.every(strName => IsOwnData(Record, strName)) && (Object.keys(Nested).join(",") === vecNestedFields.join(",")) && vecNestedFields.every(strName => IsOwnData(Nested, strName));
	const bValues = bCommand ? ((Record.CONTINUE === 0) && (Record.BLOCK === 1) && (Record.HANDLED === 1) && (Nested.Continue === 0) && (Nested.Block === 1) && (Nested.Handled === 1) && ["GetCommandReturnNumber", "GetCommandReturnObject"].every(strName => typeof Record[strName] === "function") && (BindingRecordsLegacy ? !Object.hasOwn(Record, "MAX_COMMAND_LENGTH") : (Record.MAX_COMMAND_LENGTH === BindingRecordsMaximumLength))) : ((Record.PRE === BindingRecordsPre) && (Record.POST === BindingRecordsPost) && (Nested.Pre === BindingRecordsPre) && (Nested.Post === BindingRecordsPost));

	return bOwnFields && bValues;
})()
)js")->IsTrue(), strFailure.c_str());
					++unProbeCount;
				}
			}

			Require(unProbeCount == (kFixtureLegacyBindingRecords ? kLegacyProbeCount : kModernProbeCount), "Execute every modern or legacy binding record prototype probe");

			v8::Local<v8::Object> const LocalCommandModule = v8::Object::New(pIsolate);
			Require(InstallCommandReturnBindings(pIsolate, LocalContext, LocalCommandModule), "Install actual command constant wrapper callbacks");
			Require(SetRecordProperty(pIsolate, LocalContext, LocalContext->Global(), "BindingCommandModule", LocalCommandModule), "Publish actual command constant wrappers");
			char const* const pszPreviousAPIName = g_pszExpectedConstantAPIName;
			char const* const pszPreviousModuleName = g_pszExpectedConstantModuleName;
			const BackendFault PreviousFault = g_BackendFault;
			const unsigned int unPreviousCalls = g_unBackendCalls;
			g_pszExpectedConstantModuleName = "commands";
			g_BackendFault = BackendFault::None;
			g_unBackendCalls = 0;
			g_pszExpectedConstantAPIName = "commands.GetCommandReturnNumber(strName)";
			Require(Evaluate(pIsolate, "typeof BindingCommandModule.GetCommandReturnNumber('CONTINUE') === 'number'")->IsTrue(), "Dispatch actual numeric constant wrapper");
			g_pszExpectedConstantAPIName = "commands.GetCommandReturnObject(strName)";
			Require(Evaluate(pIsolate, "typeof BindingCommandModule.GetCommandReturnObject('CommandReturn') === 'object'")->IsTrue(), "Dispatch actual object constant wrapper");
			const bool bDispatchedOnceEach = g_unBackendCalls == 2;
			g_pszExpectedConstantAPIName = pszPreviousAPIName;
			g_pszExpectedConstantModuleName = pszPreviousModuleName;
			g_BackendFault = PreviousFault;
			g_unBackendCalls = unPreviousCalls;
			Require(bDispatchedOnceEach, "Dispatch each command constant wrapper exactly once with adapted constant lookup");
		}

		void CheckEngineServerAddressRecordProperties(v8::Isolate* const pIsolate) {
			struct AddressRecordProbe {
				char const* m_pszKind;
				void const* m_pAddress;
			};

			constexpr AddressRecordProbe kProbes[] = { { "iserver", &g_Server }, { "iclient", &g_Client } };
			constexpr char const* kFieldNames[] = { "Address", "Kind" };
			constexpr std::size_t kExpectedProbeCount = 8;

			v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
			std::size_t unProbeCount = 0;
			for (auto const& Probe : kProbes) {
				const std::uintptr_t unExpectedAddress = reinterpret_cast<std::uintptr_t>(Probe.m_pAddress);
				for (auto const& pszFieldName : kFieldNames) {
					for (auto const& bAccessor : { true, false }) {
						std::string const strFailure = std::string("Initialize engine address records with own data properties: Kind=") + Probe.m_pszKind + " Field=" + pszFieldName + (bAccessor ? " Accessor" : " NonWritable");
						auto const CreateRecord = [pIsolate, LocalContext, &Probe]() -> v8::Local<v8::Object> {
							return MakeEngineServerAddressObject(pIsolate, LocalContext, Probe.m_pszKind, Probe.m_pAddress);
						};
						v8::Local<v8::Object> const LocalRecord = CheckRecordPrototypeConstruction(pIsolate, LocalContext, pszFieldName, bAccessor, CreateRecord, strFailure.c_str());

						Require(SetValue(pIsolate, LocalContext, LocalContext->Global(), "EngineAddressRecord", LocalRecord), "Publish engine address record probe result");
						std::string const strValidation = std::string("(() => { const Record = EngineAddressRecord; const vecFields = ['Address', 'Kind']; return (Object.keys(Record).join(',') === 'Address,Kind') && (Record.Kind === '") + Probe.m_pszKind + "') && (Record.Address === " + std::to_string(unExpectedAddress) + "n) && vecFields.every(strName => { const Descriptor = Object.getOwnPropertyDescriptor(Record, strName); return (Descriptor !== undefined) && Object.hasOwn(Descriptor, 'value') && Descriptor.writable && Descriptor.enumerable && Descriptor.configurable; }); })()";
						Require(Evaluate(pIsolate, strValidation.c_str())->IsTrue(), strFailure.c_str());
						++unProbeCount;
					}
				}
			}

			Require(unProbeCount == kExpectedProbeCount, "Execute all eight engine address record prototype probes");
		}

		void CheckIServerClientRecordConstruction(v8::Isolate* const pIsolate) {
			constexpr int kClientIndex = 7;
			constexpr char const* kFieldNames[] = { "Index", "DisconnectClient", "ExecuteClientStringCommand", "PrintToClientConsole", "GetUserSetting", "SetNetworkRate", "SetUpdateRate" };
			constexpr std::size_t kExpectedProbeCount = 14;

			v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
			const std::uintptr_t unClientAddress = reinterpret_cast<std::uintptr_t>(&g_Client);
			auto const CreateRecord = [pIsolate, LocalContext]() -> v8::Local<v8::Object> {
				return MakeIServerClientObject(pIsolate, LocalContext, &g_Client, kClientIndex);
			};

			std::size_t unProbeCount = 0;
			for (auto const& pszFieldName : kFieldNames) {
				for (auto const& bAccessor : { true, false }) {
					std::string const strFailure = std::string("Initialize IClient records with own fields and methods: Field=") + pszFieldName + (bAccessor ? " Accessor" : " NonWritable");
					v8::Local<v8::Object> const LocalRecord = CheckRecordPrototypeConstruction(pIsolate, LocalContext, pszFieldName, bAccessor, CreateRecord, strFailure.c_str());
					Require(SetRecordProperty(pIsolate, LocalContext, LocalContext->Global(), "ClientConstructionRecord", LocalRecord), "Publish IClient construction probe result");
					std::string const strValidation = std::string(R"js(
((unAddress) => {
	const Record = ClientConstructionRecord;
	const vecMethods = [
		"DisconnectClient",
		"ExecuteClientStringCommand",
		"PrintToClientConsole",
		"GetUserSetting",
		"SetNetworkRate",
		"SetUpdateRate",
	];
	const vecFields = [
		"Address",
		"Kind",
		"Index",
		"PlayerSlot",
		"UserID",
		"Name",
		"NetworkID",
		"Rate",
		"UpdateRate",
		"MaximumAcknowledgedTickCount",
		"Connected",
		"Spawned",
		"Active",
		"FakeClient",
		"IsHLTV",
		"NetworkChannelAddress",
		...vecMethods,
	];

	return (Object.keys(Record).join(",") === vecFields.join(",")) && vecFields.every(strName => Object.hasOwn(Record, strName)) && (Record.Address === unAddress) && (Record.Kind === "iclient") && (Record.Index === 7) && ["Address", "Kind", "Index", ...vecMethods].every(strName => {
		const Descriptor = Object.getOwnPropertyDescriptor(Record, strName);

		return Object.hasOwn(Descriptor, "value") && Descriptor.writable && Descriptor.enumerable && Descriptor.configurable;
	}) && vecMethods.every(strName => typeof Record[strName] === "function");
})
)js") + "(" + std::to_string(unClientAddress) + "n);";
					Require(Evaluate(pIsolate, strValidation.c_str())->IsTrue(), strFailure.c_str());
					++unProbeCount;
				}
			}

			Require(unProbeCount == kExpectedProbeCount, "Execute all fourteen IClient construction prototype probes");
		}

