		void CheckPlayerKick(v8::Isolate* const pIsolate) {
			constexpr int kPlayerIndex = 4;
			constexpr unsigned int kDirectFaultCalls[] = { 1, 2 };
			constexpr unsigned int kFallbackFaultCalls[] = { 1, 2, 3, 4 };

			v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
			Require(SetFunction(pIsolate, LocalContext, LocalContext->Global(), "NativeKick", PlayerKickMethodCallback, v8::Int32::New(pIsolate, kPlayerIndex)), "Register actual Kick callback");

			for (auto const& unFaultCall : kDirectFaultCalls) {
				CheckNativeExpression(pIsolate, "NativeKick()", "true", "Player.Kick()", 2, unFaultCall);
			}

			CheckNativeExpression(pIsolate, "NativeKick(null)", "true", "Player.Kick()", 2);
			g_pszExpectedPlayerText = "";
			CheckNativeExpression(pIsolate, "NativeKick('')", "true", "Player.Kick()", 2);
			g_pszExpectedPlayerText = "Fixture";
			CheckNativeExpression(pIsolate, "NativeKick('Fixture\\0Ignored')", "true", "Player.Kick()", 2);
			CheckCountedValidation(pIsolate, "(() => { for (const Value of [true, 1, {}, new String('Fixture')]) { try { NativeKick(Value); } catch (Failure) { if (Failure.message.includes('expects a message string')) { continue; } } return false; } return true; })()", 4);

			g_bPlayerConnected = false;
			CheckCountedValidation(pIsolate, "(() => { try { NativeKick({}); } catch (Failure) { return Failure.message.includes('connected player'); } return false; })()", 1);
			g_bPlayerConnected = true;

			g_bDirectPlayerDisconnect = false;
			g_pszExpectedPlayerText = "kickid 73 Kicked by SourceJS.";

			for (auto const& unFaultCall : kFallbackFaultCalls) {
				CheckNativeExpression(pIsolate, "NativeKick()", "true", "Player.Kick()", 4, unFaultCall);
			}

			CheckNativeExpression(pIsolate, "NativeKick('')", "true", "Player.Kick()", 4);
			g_pszExpectedPlayerText = "kickid 73 Fixture   Text";
			CheckNativeExpression(pIsolate, "NativeKick('Fixture;\\r\\nText')", "true", "Player.Kick()", 4);
			g_bServerCommandResult = false;
			CheckNativeExpression(pIsolate, "NativeKick('Fixture;\\r\\nText')", "false", "Player.Kick()", 4);
			g_bServerCommandResult = true;
			g_bDirectPlayerDisconnect = true;
			g_pszExpectedPlayerText = "Kicked by SourceJS.";
		}

		void CheckPlayerMethods(v8::Isolate* const pIsolate) {
			struct BanDurationProbe {
				char const* m_pszExpression;
				char const* m_pszExpectedCommand;
			};

			constexpr unsigned int kBanDispatchCount = 4;
			constexpr unsigned int kBanWithoutFlagsDispatchCount = 3;
			constexpr BanDurationProbe kBanDurationProbes[] = {
				{ "0", "banid 0 73" },
				{ "-0", "banid 0 73" },
				{ "1", "banid 1 73" },
				{ "12.0", "banid 12 73" },
				{ "2147483647", "banid 2147483647 73" },
			};
			constexpr char const* const kInvalidBanDurationExpressions[] = {
				"12.9",
				"-0.9",
				"-1",
				"-2147483648",
				"2147483648",
				"2147483647.9",
				"4294967296",
				"4294967297",
				"-2147483649",
				"-4294967296",
				"-4294967295",
				"null",
				"undefined",
				"NaN",
				"Infinity",
				"-Infinity",
				"true",
				"false",
				"''",
				"'17.9'",
				"'Invalid'",
				"Object(12)",
				"1n",
				"Object(1n)",
				"Symbol('Duration')",
				"Object(Symbol('Duration'))",
				"({})",
				"new Date(0)",
				"[]",
				"[0]",
			};

			v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
			Require(SetFunction(pIsolate, LocalContext, LocalContext->Global(), "NativeBan", PlayerBanMethodCallback, v8::Undefined(pIsolate)), "Register actual Ban callback");
			Require(SetFunction(pIsolate, LocalContext, LocalContext->Global(), "NativeChangeTeam", PlayerChangeTeamMethodCallback, v8::Undefined(pIsolate)), "Register actual ChangeTeam callback");
			g_pszExpectedCommandOperation = "Player.Ban()";
			g_pszExpectedPlayerText = "banid 0 73 kick";
			g_pszExpectedSecondCommand = "writeid";

			for (unsigned int unFaultCall = 1; unFaultCall <= kBanDispatchCount; ++unFaultCall) {
				CheckNativeExpression(pIsolate, "NativeBan()", "true", "Player.Ban()", kBanDispatchCount, unFaultCall);
			}

			g_bServerCommandResult = false;
			CheckNativeExpression(pIsolate, "NativeBan()", "false", "Player.Ban()", kBanDispatchCount);
			g_bServerCommandResult = true;

			g_bSecondServerCommandResult = false;
			CheckNativeExpression(pIsolate, "NativeBan()", "false", "Player.Ban()", kBanDispatchCount);
			g_bSecondServerCommandResult = true;

			// Validate the raw numeric duration before narrowing or reading the receiver.
			for (auto const& Probe : kBanDurationProbes) {
				g_pszExpectedPlayerText = Probe.m_pszExpectedCommand;
				std::string const strExpression = std::string("NativeBan(") + Probe.m_pszExpression + ", false, false)";
				CheckNativeExpression(pIsolate, strExpression.c_str(), "true", "Player.Ban()", kBanWithoutFlagsDispatchCount);
			}

			for (auto const& pszDurationExpression : kInvalidBanDurationExpressions) {
				std::string const strExpression = std::string("(() => { let unIndexReads = 0; const Player = { get Index() { ++unIndexReads; return 4; } }; try { NativeBan.call(Player, ") + pszDurationExpression + ", false, false); return false; } catch (Failure) { return (Failure instanceof Error) && Failure.message.includes('duration') && (unIndexReads === 0); } })()";
				CheckWithoutBackend(pIsolate, strExpression.c_str());
			}

			CheckWithoutBackend(pIsolate, "(() => { let unCoercions = 0; let unIndexReads = 0; const Marker = {}; const Player = { get Index() { ++unIndexReads; return 4; } }; const vecValues = [{ valueOf() { ++unCoercions; return 12; } }, { valueOf() { ++unCoercions; throw Marker; } }, { [Symbol.toPrimitive]() { ++unCoercions; throw Marker; } }, { get valueOf() { ++unCoercions; return () => 12; } }, new Proxy({}, { get() { ++unCoercions; throw Marker; } })]; for (const Value of vecValues) { try { NativeBan.call(Player, Value, false, false); return false; } catch (Failure) { if (!(Failure instanceof Error) || !Failure.message.includes('duration')) { return false; } } } return (unCoercions === 0) && (unIndexReads === 0); })()");

			g_pszExpectedPlayerText = "banid 0 73 kick";
			CheckWithoutBackend(pIsolate, "(() => { let unReads = 0; const Player = { get Index() { ++unReads; return 4; } }; const vecArguments = [[-1], [0, null], [0, undefined], [0, new Boolean(true)], [0, true, null], [0, true, undefined], [0, true, {}]]; for (const vecEntry of vecArguments) { try { NativeBan.apply(Player, vecEntry); return false; } catch (Failure) { if (!(Failure instanceof Error)) { return false; } } } return unReads === 0; })()");
			CheckWithoutBackend(pIsolate, "(() => { const Marker = {}; try { NativeBan.call({ get Index() { throw Marker; } }); return false; } catch (Failure) { return Failure === Marker; } })()");

			g_bPlayerConnected = false;
			CheckCountedValidation(pIsolate, "(() => { try { NativeBan(); return false; } catch (Failure) { return Failure.message.includes('connected player'); } })()", 1);
			g_bPlayerConnected = true;

			g_bPlayerAvailable = false;
			CheckWithoutBackend(pIsolate, "(() => { try { NativeBan(); return false; } catch (Failure) { return Failure.message === 'Synthetic player lookup unavailable.'; } })()");
			CheckWithoutBackend(pIsolate, "(() => { try { NativeChangeTeam({}); return false; } catch (Failure) { return Failure.message === 'Synthetic player lookup unavailable.'; } })()");
			g_bPlayerAvailable = true;

			CheckNativeExpression(pIsolate, "NativeChangeTeam(3)", "true", "Player.ChangeTeam()");
			CheckNativeExpression(pIsolate, "NativeChangeTeam('FixtureTeam')", "true", "Player.ChangeTeam()");
			CheckWithoutBackend(pIsolate, "(() => { for (const Value of [undefined, null, -1, 1.5, NaN, Infinity, true, {}, new String('FixtureTeam'), 'UnknownTeam']) { try { NativeChangeTeam(Value); return false; } catch (Failure) { if (!(Failure instanceof Error)) { return false; } } } return true; })()");
			CheckWithoutBackend(pIsolate, "(() => { const Marker = {}; try { NativeChangeTeam.call({ get Index() { throw Marker; } }, {}); return false; } catch (Failure) { return Failure === Marker; } })()");
			CheckWithoutBackend(pIsolate, "(() => { try { NativeChangeTeam('UnavailableTeam'); return false; } catch (Failure) { return Failure.message === 'Synthetic team data unavailable.'; } })()");
			g_pszExpectedCommandOperation = "Player.Kick()";
			g_pszExpectedPlayerText = "Kicked by SourceJS.";
		}

		void CheckPlayerCommandMethods(v8::Isolate* const pIsolate) {
			// Constructor-free, fully initialized test-vector records.
			struct PlayerCommandProbe {
				char const* m_pszName;
				v8::FunctionCallback m_Callback;
				char const* m_pszOperation;
				char const* m_pszCommand;
				bool m_bServerSide;
			};

			constexpr PlayerCommandProbe kProbes[] = {
				{ "NativeSend", SendClientCommandCallback, "commands.Send()", "Fixture", false },
				{ "NativeSay", SayCallback, "commands.Say()", "say \"Fixture\"", true },
				{ "NativeSayTeam", SayToTeamCallback, "commands.SayTeam()", "say_team \"Fixture\"", true },
			};

			v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
			g_bCheckClientCommandArguments = true;

			for (auto const& Probe : kProbes) {
				Require(SetFunction(pIsolate, LocalContext, LocalContext->Global(), Probe.m_pszName, Probe.m_Callback, v8::Undefined(pIsolate)), "Register actual player command callback");
				g_pszExpectedClientOperation = Probe.m_pszOperation;
				g_pszExpectedClientCommand = Probe.m_pszCommand;
				g_bExpectedClientServerSide = Probe.m_bServerSide;
				std::string const strCall = std::string(Probe.m_pszName) + "({ Index: 4 }, 'Fixture')";
				CheckNativeExpression(pIsolate, strCall.c_str(), "true", Probe.m_pszOperation);
				g_bClientCommandResult = false;
				CheckNativeExpression(pIsolate, strCall.c_str(), "false", Probe.m_pszOperation);
				g_bClientCommandResult = true;

				std::string const strValidation = std::string("(() => { const Marker = {}; const Player = { get Index() { throw Marker; } }; for (const Value of [null, undefined, true, 1, {}, new String('Fixture')]) { try { ") + Probe.m_pszName + "(Player, Value); return false; } catch (Failure) { if (!(Failure instanceof Error)) { return false; } } } try { " + Probe.m_pszName + "(Player, 'Fixture'); return false; } catch (Failure) { return Failure === Marker; } })()";
				CheckWithoutBackend(pIsolate, strValidation.c_str());
			}

			g_pszExpectedClientOperation = "commands.Send()";
			g_pszExpectedClientCommand = "Fixture";
			g_bExpectedClientServerSide = false;
			CheckNativeExpression(pIsolate, "NativeSend(4, 'Fixture', null)", "true", "commands.Send()");
			CheckNativeExpression(pIsolate, "NativeSend(4, 'Fixture', undefined)", "true", "commands.Send()");
			g_bExpectedClientServerSide = true;
			CheckNativeExpression(pIsolate, "NativeSend(4, 'Fixture', true)", "true", "commands.Send()");
			CheckWithoutBackend(pIsolate, "(() => { for (const Value of [1, 'true', {}, new Boolean(true)]) { try { NativeSend(4, 'Fixture', Value); return false; } catch (Failure) { if (!(Failure instanceof Error)) { return false; } } } const Marker = {}; try { NativeSend({ get Index() { throw Marker; } }, 'Fixture', {}); return false; } catch (Failure) { return Failure === Marker; } })()");

			g_pszExpectedClientOperation = "commands.Say()";
			g_pszExpectedClientCommand = "say \"A\\\"B\\\\C  D\"";
			CheckNativeExpression(pIsolate, "NativeSay(4, 'A\"B\\\\C\\r\\nD')", "true", "commands.Say()");

			g_pszExpectedClientOperation = "commands.SayTeam()";
			g_pszExpectedClientCommand = "say_team \"A\\\"B\\\\C  D\"";
			CheckNativeExpression(pIsolate, "NativeSayTeam(4, 'A\"B\\\\C\\r\\nD')", "true", "commands.SayTeam()");
			g_bCheckClientCommandArguments = false;
		}

