			IGameEvent Event {};
			Require(SetValue(pIsolate, LocalContext, LocalContext->Global(), "FixtureDirectEventAddress", v8::BigInt::NewFromUnsigned(pIsolate, static_cast<std::uint64_t>(reinterpret_cast<std::uintptr_t>(&Event)))), "Publish borrowed direct-access event address");
