			Require(InstallEventHookUInt64Functions<IGameEvent>(pIsolate, LocalContext, LocalUInt64Module, v8::Undefined(pIsolate)), "Install actual SDK-gated uint64 event functions");
			Require(SetValue(pIsolate, LocalContext, LocalContext->Global(), "FixtureEventUInt64", LocalUInt64Module), "Publish uint64 event capability module");
