			Require(Evaluate(pIsolate, "(typeof FixtureEventUInt64.GetUInt64 === 'function') && (typeof FixtureEventUInt64.SetUInt64 === 'function')")->IsTrue(), "Expose both uint64 methods when the selected SDK supports them");
#else
			Require(Evaluate(pIsolate, "!Object.hasOwn(FixtureEventUInt64, 'GetUInt64') && !Object.hasOwn(FixtureEventUInt64, 'SetUInt64')")->IsTrue(), "Omit both uint64 methods for an unsupported selected SDK");
#endif

			for (auto const& Probe : kCallbackProbes) {
				std::string const strBinding = std::string("FixtureDirect") + Probe.m_pszName;
				Require(SetFunction(pIsolate, LocalContext, LocalContext->Global(), strBinding.c_str(), Probe.m_Callback, v8::Undefined(pIsolate)), "Install actual direct-access event callback");

				// Ownership-consuming FreeEvent is exercised separately with an owned event.
				if (Probe.m_pszResult) {
					Require(Evaluate(pIsolate, Probe.m_pszResult)->IsTrue(), "Preserve direct-access event results and exact BigInt defaults");
				}

				for (auto const& Fault : { MessageFault::CppException, MessageFault::PendingCppException }) {
					std::string const strExpected = (Fault == MessageFault::PendingCppException) ? "Failure === true" : (std::string("(Failure instanceof Error) && (Failure.message === 'memory/hooks/events.") + Probe.m_pszName + "() failed with a C++ exception.')");
					std::string const strProbe = std::string("(() => { try { ") + strBinding + "(" + Probe.m_pszArguments + "); } catch (Failure) { return " + strExpected + "; } return false; })()";
					CheckEventFaultProbe(pIsolate, strProbe.c_str(), Fault, kFirstConversionCall, false, true);
				}
			}

			Require(Event.m_bValue && (Event.m_nValue == 73) && (Event.m_flValue == 1.5F) && (Event.m_strValue == "Text"), "Commit each typed direct-access setter value");
			Require(Evaluate(pIsolate, "(FixtureDirectGetFloat(FixtureDirectEventAddress, 'Value') === 1.5) && (FixtureDirectGetFloat(FixtureDirectEventAddress, 'Missing') === 0) && (FixtureDirectGetFloat(FixtureDirectEventAddress, 'Missing', '2.5') === 2.5) && (FixtureDirectSetInt(FixtureDirectEventAddress, 'Value', 4294967297) === true) && (FixtureDirectSetFloat(FixtureDirectEventAddress, 'Value', '2.5') === true)")->IsTrue() && (Event.m_nValue == 1) && (Event.m_flValue == 2.5F), "Preserve existing NumberValue/Int32Value coercion rather than invent stricter numeric contracts");
			Require(Evaluate(pIsolate, "(FixtureDirectGetString(FixtureDirectEventAddress, 'Missing') === '') && (FixtureDirectGetString(FixtureDirectEventAddress, 'Null') === '') && (FixtureDirectSetString(FixtureDirectEventAddress, 'Value', 'Text\\u0410') === true) && (FixtureDirectGetString(FixtureDirectEventAddress, 'Value') === 'Text\\u0410')")->IsTrue() && (Event.m_strValue == "Text\xD0\x90"), "Preserve exact UTF-8 bytes independently of the compiler source encoding");
			Require(Evaluate(pIsolate, "(FixtureDirectSetString(FixtureDirectEventAddress, 'Value', '') === true) && (FixtureDirectGetString(FixtureDirectEventAddress, 'Value') === '')")->IsTrue(), "Preserve empty direct-access string values");
