			Require(SetRecordProperty(pIsolate, LocalContext, LocalContext->Global(), "FixtureGetTextMessage", LocalGetMessage) && SetRecordProperty(pIsolate, LocalContext, LocalContext->Global(), "FixtureResetTextMessage", LocalReset) && SetRecordProperty(pIsolate, LocalContext, LocalContext->Global(), "FixtureMutateTextMessage", LocalMutate), "Publish text-message snapshot fixture callbacks");
