		void ConfigureFixturePVSSnapshotCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr int kNullRecordMode = 1;
			constexpr int kNullClustersMode = 2;
			constexpr int kZeroCountMode = 3;
			constexpr int kNegativeCountMode = 4;
			constexpr int kMaximumCountMode = 5;
			constexpr int kAllocationFailureMode = 6;

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if ((CallbackInformation.Length() != 1) || !CallbackInformation[0]->IsInt32()) {
				ThrowError(pIsolate, "Controlled PVS snapshot requires one int32 mode.");
				return;
			}

			const int nMode = CallbackInformation[0].As<v8::Int32>()->Value();
			if ((nMode < 0) || (nMode > kAllocationFailureMode)) {
				ThrowError(pIsolate, "Unknown controlled PVS snapshot mode.");
				return;
			}

			for (std::size_t unIndex = 0; unIndex < kFixturePVSClusterCapacity; ++unIndex) {
				g_arrFixturePVSClusters[unIndex] = static_cast<unsigned short>(unIndex);
			}

			g_arrFixturePVSClusters[0] = 11;
			g_arrFixturePVSClusters[1] = 22;
			g_arrFixturePVSClusters[2] = 33;
			g_FixturePVSInformation = { 7, 3, g_arrFixturePVSClusters, 4, 5, { 1, 2, 3 } };
			g_pFixturePVSInformation = (nMode == kNullRecordMode) ? nullptr : &g_FixturePVSInformation;
			g_bFixturePVSSnapshotAllocationFailure = nMode == kAllocationFailureMode;

			if (nMode == kNullClustersMode) {
				g_FixturePVSInformation.m_pClusters = nullptr;

			} else if (nMode == kZeroCountMode) {
				g_FixturePVSInformation.m_nClusterCount = 0;

			} else if (nMode == kNegativeCountMode) {
				g_FixturePVSInformation.m_nClusterCount = -1;

			} else if (nMode == kMaximumCountMode) {
				g_FixturePVSInformation.m_nClusterCount = static_cast<short>(kFixturePVSClusterCapacity);
			}

			CallbackInformation.GetReturnValue().Set(v8::BigInt::NewFromUnsigned(pIsolate, reinterpret_cast<std::uintptr_t>(g_pFixturePVSInformation)));
		}

