int main() {
	if (!v8::V8::InitializeICUDefaultLocation(nullptr)) {
		std::fprintf(stderr, "Module binding error fixture: V8 ICU initialization failed.\n");
		return 2;
	}

	v8::V8::InitializeExternalStartupData(nullptr);
	std::unique_ptr<v8::Platform> pPlatform = v8::platform::NewDefaultPlatform();
	if (!pPlatform) {
		std::fprintf(stderr, "Module binding error fixture: Create V8 platform failed.\n");
		return 2;
	}

	v8::V8::InitializePlatform(pPlatform.get());

	if (!v8::V8::Initialize()) {
		v8::V8::DisposePlatform();
		std::fprintf(stderr, "Module binding error fixture: V8 initialization failed.\n");
		return 2;
	}

	int nResult = 0;

	try {
		SourceJS::RunFixture();
	} catch (std::exception const& Failure) {
		std::fprintf(stderr, "Module binding error fixture: %s\n", Failure.what());
		nResult = 1;
	}

	if (!v8::V8::Dispose()) {
		std::fprintf(stderr, "Module binding error fixture: V8 disposal failed.\n");
		nResult = 1;
	}

	v8::V8::DisposePlatform();

	return nResult;
}
