	V8Runtime::V8Runtime(v8::Isolate* const pIsolate) :
		m_pIsolate(pIsolate)
	{
	}

	bool V8Runtime::RequirePluginLocalModule(std::string const&, std::string const&, v8::Local<v8::Value>&) {
		auto* const pIsolate = v8::Isolate::GetCurrent();
		if (g_RelativeFaultMode == FaultMode::Terminated) {
			v8::Local<v8::Script> LocalScript {};
			if (!v8::Script::Compile(pIsolate->GetCurrentContext(), FixtureString(pIsolate, "0")).ToLocal(&LocalScript)) {
				return false;
			}

			pIsolate->TerminateExecution();
			v8::Local<v8::Value> LocalResult {};
			if (LocalScript->Run(pIsolate->GetCurrentContext()).ToLocal(&LocalResult)) {
				throw std::runtime_error("Fixture termination was not delivered");
			}

			return false;
		}

		if ((g_RelativeFaultMode == FaultMode::JavaScript) || (g_RelativeFaultMode == FaultMode::JavaScriptAndNativeException)) {
			pIsolate->ThrowException(GetGlobal(pIsolate, pIsolate->GetCurrentContext(), "g_OriginalFailure"));
		}

		if ((g_RelativeFaultMode == FaultMode::NativeException) || (g_RelativeFaultMode == FaultMode::JavaScriptAndNativeException)) {
			throw std::runtime_error("Injected local-loader native exception");
		}

		return false;
	}

